    0: [1, 2],
    1: [0, 2],
    2: [0, 1],
    3: [4],
    4: [3]
}

visited = set()
components = 0

def traverse(node):
    stack = [node]
    while stack:
        current = stack.pop()
        if current not in visited:
            visited.add(current)
            for neighbor in graph.get(current, []):
                if neighbor not in visited:
                    stack.append(neighbor)

for node in graph:
    if node not in visited:
        traverse(node)
        components += 1

print('Number of connected components:', components)

